// Formata prompt com relatório técnico
const { relatorio_tecnico, systemMessage } = $input.item.json;

const prompt = [
  systemMessage,
  ``,
  `RELATÓRIO TÉCNICO A SER HUMANIZADO:`,
  ``,
  relatorio_tecnico,
  ``,
  `---`,
  ``,
  `Por favor, gere o relatório humanizado seguindo as diretrizes acima.`
].join('\n');

return { prompt };

// Formata resposta
const relatorio_humanizado = $('Processa Humanizacao').first().json.output;
const input = $('Prepara Humanizacao').first().json;

return {
  code: 200,
  data: {
    relatorio_humanizado,
    relatorio_original: input.relatorio_tecnico,
    metadados: {
      tipo: input.tipo,
      destinatario: input.destinatario,
      tom: input.tom,
      data_processamento: new Date().toISOString()
    }
  }
};
